def verdopple_minus_eins(n):
    return 2 * n - 1

def kombiniere(a, b):
    return verdopple_minus_eins(a) + b

ergebnis = kombiniere(4, 3)
zwischenspeicher = verdopple_minus_eins(ergebnis)

def flaeche(a, b):
    return a * b

def umfang(a, b):
    return 2 * (a + b)

print(flaeche(3, 4), umfang(3, 4))
